'use strict';
const status=document.querySelector('#status'),cards=document.querySelector('#cards'),journal=document.querySelector('#journal'),select=document.querySelector('#scenario');let sequence=0,controller;
function state(kind,message){status.dataset.state=kind;status.textContent=message;}
function validate(data){if(!Array.isArray(data))throw new Error('Le document doit être un tableau JSON.');if(data.length>50)throw new Error('Le laboratoire accepte au plus 50 projets.');const ids=new Set();for(const item of data){if(!item||typeof item!=='object')throw new Error('Chaque projet doit être un objet.');for(const key of ['id','titre','description','action','lien'])if(typeof item[key]!=='string'||!item[key].trim()||item[key].length>700)throw new Error('Champ absent ou invalide : '+key);if(ids.has(item.id))throw new Error('Identifiant en double : '+item.id);ids.add(item.id);if(!/^pieces\/[a-z0-9_-]+\.html$/i.test(item.lien))throw new Error('Le lien doit viser une fiche HTML dans pieces/.');}return data;}
function show(data){cards.replaceChildren();for(const p of data){const article=document.createElement('article'),id=document.createElement('small'),title=document.createElement('h2'),description=document.createElement('p'),a=document.createElement('a');id.textContent=p.id;title.textContent=p.titre;description.textContent=p.description;a.textContent=p.action;a.href=p.lien;article.append(id,title,description,a);cards.append(article);}}
async function load(){const run=++sequence;if(controller)controller.abort();controller=new AbortController();cards.replaceChildren();if(location.protocol==='file:'){state('error','Ouverture directe détectée. Servez ce dossier sur localhost pour lancer fetch.');journal.textContent='Dans le dossier laboratoire-json :\npython -m http.server 8000\nPuis ouvrir http://localhost:8000/\nAucune installation supplémentaire requise si Python est déjà disponible.';return;}const url='data/'+select.value;state('loading','Chargement des données…');journal.textContent='GET '+url+'\nÉtat : chargement';const timeout=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(url,{signal:controller.signal,cache:'no-store'});if(!response.ok)throw new Error('Réponse HTTP '+response.status+' pour '+url);const body=await response.text();let payload;try{payload=JSON.parse(body)}catch{throw new Error('Syntaxe JSON invalide. Vérifiez les guillemets et les virgules.')}const data=validate(payload);if(run!==sequence)return;show(data);state(data.length?'success':'empty',data.length?data.length+' projets chargés.':'Aucun projet disponible dans ce tableau.');journal.textContent='GET '+url+'\nHTTP '+response.status+'\nJSON : tableau validé\nObjets : '+data.length+'\nÉtat : '+(data.length?'succès':'vide');}catch(error){if(run!==sequence)return;state('error','Chargement impossible. '+(error.name==='AbortError'?'Délai dépassé. Réessayez.':error.message));journal.textContent='GET '+url+'\nÉtat : erreur\n'+error.message+'\nChoisissez un autre scénario ou rechargez après correction.';}finally{clearTimeout(timeout);}}
document.querySelector('#load').addEventListener('click',load);load();
